#!/bin/bash
################################################################################
# Script: post_test_result.sh
# Description: Posts the test result notification generated by
#              parse_test_result.sh. Reads testResultMessage.json and sends it
#              to the configured webhook in the provider's format.
# Usage: Called from CI/CD pipeline after parse_test_result.sh
#        Source this script and call share_test_result function
# Dependencies: curl, jq, scripts/bash/notify.sh
# Environment Variables Required:
#   - NOTIFY_WEBHOOK_URL: Incoming webhook URL (empty skips the notification)
#   - NOTIFY_PROVIDER: slack (default), teams, discord, googlechat, mattermost, generic
# Input: testResultMessage.json (generated by parse_test_result.sh)
################################################################################

source ./scripts/bash/notify.sh

function share_test_result() {
    local message_file="testResultMessage.json"

    # Check if the message file exists
    if [[ ! -f "${message_file}" ]]; then
        echo "Error: Message file '${message_file}' not found."
        return 1
    fi

    notify_send_message "$(cat "${message_file}")"
}
